  const heroBolts = makeBolts(document.getElementById("bolts"), { animate: true });
  const cardBolts = makeBolts(document.getElementById("bolts-card"), { animate: false });
  requestAnimationFrame(() => { heroBolts && heroBolts.start(); cardBolts && cardBolts.start(); });
  addEventListener("load", () => { heroBolts && heroBolts.start(); cardBolts && cardBolts.start(); });

  /* ── La maquette ───────────────────────────────────────────────────── */
  const stack = document.getElementById("stack");
  const planes = [...stack.querySelectorAll(".plane")];
  const byLayer = Object.fromEntries(planes.map((p) => [p.dataset.layer, p]));

  // « Comme à l'écran » : une seule image. Les plans sont coplanaires — les
  // 0,5 px d'écart ne servent qu'à fixer l'ordre de tracé (sans eux, deux plans
  // exactement à la même profondeur scintillent), et sont invisibles à cette
  // perspective.
  const VIEWS = {
    exploded: { base: 0, reflectivity: 96, rain: 192, composite: null, lightning: 288 },
    flattened: { base: 0, reflectivity: null, rain: null, composite: 0.5, lightning: 1 },
  };

  /* Ces décalages sont en pixels absolus, alors que la scène, elle, est
     proportionnelle. Sur un téléphone, les 288 px du plan le plus haut faisaient
     monter la pile bien au-dessus de sa boîte, jusque par-dessus les commandes.
     On les met donc à l'échelle de la scène. Au-delà de 1000 px — la mise en
     page de bureau — le facteur vaut exactement 1 : rien n'y change. */
  const wideView = matchMedia("(min-width: 1000px)");
  function zScale() {
    if (wideView.matches) return 1;
    const w = scene.clientWidth;
    return w ? Math.min(1, w / 680) : 1;
  }

  let view = "exploded";

  function applyView() {
    const map = VIEWS[view];
    const k = zScale();
    stack.classList.toggle("is-flat", view === "flattened");
    for (const [layer, z] of Object.entries(map)) {
      const el = byLayer[layer];
      if (!el) continue;
      el.classList.toggle("is-hidden", z === null);
      if (z !== null) el.style.transform = "translateZ(" + z * k + "px)";
    }
  }

  for (const btn of document.querySelectorAll(".seg button")) {
    btn.addEventListener("click", () => {
      view = btn.dataset.view;
      for (const b of document.querySelectorAll(".seg button")) {
        b.setAttribute("aria-pressed", String(b === btn));
      }
      applyView();
    });
  }

  function solo(layer) {
    const map = VIEWS[view];
    for (const p of planes) {
      const shown = map[p.dataset.layer] !== null;
      p.classList.toggle("is-dimmed", shown && layer !== null && p.dataset.layer !== layer);
    }
  }
  for (const chip of document.querySelectorAll(".chip")) {
    const layer = chip.dataset.solo;
    // À plat, les plans pluie et halo disparaissent : le plan combiné les remplace.
    const on = () => solo(VIEWS[view][layer] === null ? "composite" : layer);
    chip.addEventListener("mouseenter", on);
    chip.addEventListener("focus", on);
    chip.addEventListener("click", on);
    chip.addEventListener("mouseleave", () => solo(null));
    chip.addEventListener("blur", () => solo(null));
  }

  /* Glisser pour tourner (horizontal) et incliner (vertical). */
  let spin = -34, tilt = 58, dragging = false, lastX = 0, lastY = 0;
  const scene = document.querySelector(".scene");

  function setSpin(v) {
    spin = Math.max(-95, Math.min(28, v));
    stack.style.setProperty("--spin", spin + "deg");
  }

  /* Bornes de l'inclinaison : on laisse aller jusqu'aux deux vues extrêmes — de
     face (les plans se recouvrent) et par la tranche (des lamelles) — puisque
     l'une comme l'autre se rattrape d'un geste. On s'arrête juste avant 90°,
     seule valeur vraiment perdue : les feuilles y disparaissent, et au-delà on
     passerait derrière, où la carte s'afficherait en miroir. */
  function setTilt(v) {
    tilt = Math.max(8, Math.min(86, v));
    stack.style.setProperty("--tilt", tilt + "deg");
  }

  scene.addEventListener("pointerdown", (e) => {
    // Souris et stylet seulement : capturer le tactile ici bloquerait le
    // défilement vertical de la page.
    if (e.pointerType === "touch") return;
    dragging = true;
    lastX = e.clientX;
    lastY = e.clientY;
    stack.style.transition = "none";
    scene.setPointerCapture(e.pointerId);
  });
  scene.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    setSpin(spin - (e.clientX - lastX) * 0.175);
    // Tirer vers le bas redresse les plans face à soi, pousser vers le haut
    // les couche à plat.
    setTilt(tilt - (e.clientY - lastY) * 0.25);
    lastX = e.clientX;
    lastY = e.clientY;
  });
  const endDrag = (e) => {
    if (!dragging) return;
    dragging = false;
    stack.style.transition = "";
    try { scene.releasePointerCapture(e.pointerId); } catch {}
  };
  scene.addEventListener("pointerup", endDrag);
  scene.addEventListener("pointercancel", endDrag);

  applyView();
  setSpin(spin);
  setTilt(tilt);
  // La largeur de la scène règle l'écartement : rotation d'écran comprise.
  addEventListener("resize", applyView);
